// ============================================================
// THĂM DÒ NGUỒN DỮ LIỆU CƠ BẢN (P/E, P/B, ROE, nợ, tăng trưởng)
// Mã thử: VNM. Chạy xong gửi kết quả (tab JSON) để chọn nguồn sống.
// Lưu ý: TCBS api GIÁ (stock-insight) đã chết 404, nhưng nhánh
// tcanalysis (dữ liệu cơ bản) là service KHÁC - cần kiểm tra riêng.
// ============================================================
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const H = { 'User-Agent': UA, 'Accept': 'application/json, text/plain, */*' };

const sources = [
  {
    name: 'A. TCBS - tổng quan (overview)',
    url: 'https://apipubaws.tcbs.com.vn/tcanalysis/v1/ticker/VNM/overview',
    headers: H,
  },
  {
    name: 'B. TCBS - chỉ số tài chính (quý)',
    url: 'https://apipubaws.tcbs.com.vn/tcanalysis/v1/finance/VNM/financialratio?yearly=0&isAll=false',
    headers: H,
  },
  {
    name: 'C. TCBS - chỉ số tài chính (năm)',
    url: 'https://apipubaws.tcbs.com.vn/tcanalysis/v1/finance/VNM/financialratio?yearly=1&isAll=false',
    headers: H,
  },
  {
    name: 'D. TCBS - định giá/rating',
    url: 'https://apipubaws.tcbs.com.vn/tcanalysis/v1/rating/VNM/general?fType=TICKER',
    headers: H,
  },
  {
    name: 'E. VNDirect finfo - ratios',
    url: 'https://api-finfo.vndirect.com.vn/v4/ratios/latest?order=reportDate&where=code:VNM&filter=ratioCode:PRICE_TO_EARNINGS,PRICE_TO_BOOK,ROE,ROA,DEBT_EQUITY&fields=ratioCode,value,reportDate',
    headers: { ...H, Referer: 'https://dstock.vndirect.com.vn/' },
  },
  {
    name: 'F. Simplize - overview',
    url: 'https://api.simplize.vn/api/company/overview/VNM',
    headers: H,
  },
];

const results = [];
for (const s of sources) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: s.url, headers: s.headers, json: false, timeout: 20000,
    });
    const body = typeof res === 'string' ? res : JSON.stringify(res);
    results.push({ source: s.name, status: '✅ SỐNG', sample: body.slice(0, 600) });
  } catch (e) {
    results.push({ source: s.name, status: '❌ ' + (e.message || String(e)), sample: '' });
  }
}

return results.map(r => ({ json: r }));
